 [b('Criterio de selección en el cátodo','Katodoan hautatzeko irizpidea'),b('Gana la semirreacción con E<sub>reducción,efectivo</sub> mayor.','E<sub>erredukzio,eraginkor</sub> handiena duen erdi-erreakzioak irabazten du.')],
 [b('Criterio de selección en el ánodo','Anodoan hautatzeko irizpidea'),b('Escribe todos los pares como reducciones: se oxida el de menor E<sub>efectivo</sub>.','Idatzi bikote guztiak erredukzio gisa: E<sub>eraginkor</sub> txikiena duena oxidatzen da.')],
 [b('Nernst a 25 °C','Nernst 25 °C-an'),'E = E° − (0,0592 V/n) log Q'],
 [b('¿Cómo se aplica η?','Nola aplikatzen da η?'),b('Cátodo: E<sub>teor</sub>−η; ánodo: E<sub>teor</sub>+η.','Katodoa: E<sub>teor</sub>−η; anodoa: E<sub>teor</sub>+η.')],
 [b('Fuente mínima ideal','Iturri idealaren gutxienekoa'),b('E<sub>aplicada,min</sub> = E<sub>ánodo,ef</sub> − E<sub>cátodo,ef</sub> = −E<sub>celda</sub>.','E<sub>aplikatu,min</sub> = E<sub>anodo,erag</sub> − E<sub>katodo,erag</sub> = −E<sub>zelda</sub>.')]
