 [b('¿Qué efecto tiene el sobrepotencial del hidrógeno?','Zer eragiten du hidrogenoaren gaintentsioak?'),b('Katodoan E(H₂) jaisten du; nikel metaketa lehenestea ahalbidetu dezake.','Katodoan E(H₂) jaisten du; nikel metaketa lehenestea ahalbidetu dezake.')],
 [b('2022-23 ez-ohikoa 3.c-ren oharra','2022-23 ez-ohikoa 3.c-ren oharra'),b('Anodoan Pt egokia da; edozein katodo metaliko erabiltzea lan-baldintzen araberakoa da (Zn-k erreakzionatu dezake).','Anodoan Pt egokia da; edozein katodo metaliko erabiltzea lan-baldintzen araberakoa da (Zn-k erreakzionatu dezake).')]
