const X=[
 {id:'EL-01',lvl:0,skill:b('Zelula-potentziala eta ΔG','Zelula-potentziala eta ΔG'),title:b('Uraren elektrolisiaren energia','Uraren elektrolisiaren energia'),q:b('2H₂O(l) → 2H₂(g)+O₂(g) erreakzioaren ΔG°=+474,4 kJ da, 4 mol e⁻ transferituz. Kalkulatu (a) E° (V) eta (b) espontaneotasunari buruzko ondorioa.','2H₂O(l) → 2H₂(g)+O₂(g) erreakzioaren ΔG°=+474,4 kJ da, 4 mol e⁻ transferituz. Kalkulatu (a) E° (V) eta (b) espontaneotasunari buruzko ondorioa.'),parts:[{q:b('E° (V)','E° (V)'),ans:-1.229,tol:0.01},{q:b('ΔG°-ren zeinua (+1 edo −1)','ΔG°-ren zeinua (+1 edo −1)'),ans:1,abs:0}],hints:[b('Erabili ΔG°=−nFE°.','Erabili ΔG°=−nFE°.'),b('Bihurtu 474,4 kJ joule eta hartu n=4.','Bihurtu 474,4 kJ joule eta hartu n=4.')],sol:[b('E°=−ΔG°/(nF)=−474400/(4·96485)=<b>−1,229 V</b>.','E°=−ΔG°/(nF)=−474400/(4·96485)=<b>−1,229 V</b>.'),b('ΔG° positiboa da; erreakzioa idatzitako noranzkoan ez da espontaneoa eta kanpoko lana behar du.','ΔG° positiboa da; erreakzioa idatzitako noranzkoan ez da espontaneoa eta kanpoko lana behar du.')],res:b('E°=−1,229 V; ΔG°>0, ez-espontaneoa.','E°=−1,229 V; ΔG°>0, ez-espontaneoa.'),check:b('E negatiboak ΔG=−nFE-ren bidez ΔG positiboa ematen du.','E negatiboak ΔG=−nFE-ren bidez ΔG positiboa ematen du.'),errs:b('kJ zuzenean F-rekin erabiltzea edo E-ren zeinua galtzea.','kJ zuzenean F-rekin erabiltzea edo E-ren zeinua galtzea.')},
 {id:'EL-02',lvl:0,skill:b('Karga eta metatutako masa','Karga eta metatutako masa'),title:b('Kobrezko objektu bat estali','Kobrezko objektu bat estali'),q:b('Cu²⁺+2e⁻→Cu(s). Elektrolizatzailean 1,80 A-ko korrontea 25,0 min-an igarotzen da. Kalkulatu (a) karga eta (b) katodoan metatutako kobre-masa (M=63,546 g·mol⁻¹).','Cu²⁺+2e⁻→Cu(s). Elektrolizatzailean 1,80 A-ko korrontea 25,0 min-an igarotzen da. Kalkulatu (a) karga eta (b) katodoan metatutako kobre-masa (M=63,546 g·mol⁻¹).'),parts:[{q:b('Q (C)','Q (C)'),ans:2700,abs:2},{q:b('m(Cu) (g)','m(Cu) (g)'),ans:0.8891,tol:0.02}],hints:[b('Bihurtu 25,0 min segundotara.','Bihurtu 25,0 min segundotara.'),b('Q=It; ondoren ne=Q/F eta nCu=ne/2.','Q=It; ondoren ne=Q/F eta nCu=ne/2.')],sol:[b('t=25,0·60=1500 s; Q=1,80·1500=<b>2700 C</b>.','t=25,0·60=1500 s; Q=1,80·1500=<b>2700 C</b>.'),b('n(e⁻)=2700/96485=0,02798 mol; n(Cu)=0,01399 mol; m=nM=<b>0,889 g</b>.','n(e⁻)=2700/96485=0,02798 mol; n(Cu)=0,01399 mol; m=nM=<b>0,889 g</b>.')],res:b('2700 C; 0,889 g Cu.','2700 C; 0,889 g Cu.'),check:b('Q/F=0,02798 mol e⁻; 2 e⁻/Cu mol bakoitzeko.','Q/F=0,02798 mol e⁻; 2 e⁻/Cu mol bakoitzeko.'),errs:b('t minututan uztea edo Cu²⁺-rentzat elektroi-koefizientea ez erabiltzea.','t minututan uztea edo Cu²⁺-rentzat elektroi-koefizientea ez erabiltzea.')},
{id:'EL-03',lvl:1,skill:b('Nernst eta pH-a','Nernst and pH'),title:b('Hidrogeno-elektrodoaren potentziala','Potencial del electrodo de hidrógeno'),q:b('25 °C-an, 2H⁺+2e⁻→H₂(g), E°=0, [H⁺]=1,00×10⁻² M eta P(H₂)=1,00 bar. Kalkulatu E.','A 25 °C, 2H⁺+2e⁻→H₂(g), E°=0, [H⁺]=1,00×10⁻² M y P(H₂)=1,00 bar. Calcula E.'),parts:[{q:b('E (V)','E (V)'),ans:-0.1184,abs:0.002}],hints:[b('Q=P(H₂)/[H⁺]² da.','Q=P(H₂)/[H⁺]².'),b('Ordezkatu E=E°−(0,0592/2)logQ.','Sustituye E=E°−(0,0592/2)logQ.')],sol:[b('Q=1/(10⁻²)²=10⁴.','Q=1/(10⁻²)²=10⁴.'),b('E=0−(0,0592/2)·4=<b>−0,1184 V</b>.','E=0−(0,0592/2)·4=<b>−0,1184 V</b>.')],res:'−0,1184 V',check:b('[H⁺] lau aldiz handiagoa balitz, E positiboagoa litzateke; zeinuaren noranzkoa koherentea da.','Si [H⁺] fuera cuatro veces mayor, E sería más positivo; el sentido del signo es coherente.'),errs:b('Erreakzioa 2 elektroi dituela ahaztu edo Q alderantziz jartzea.','Olvidar que la reacción implica 2 electrones o invertir Q.')},
 {id:'EL-04',lvl:1,skill:b('Faraday: zilarra','Faraday: zilarra'),title:b('Zilar-geruza bat metatzea','Zilar-geruza bat metatzea'),q:b('Ag⁺+e⁻→Ag(s). 1,50 A-ko korrontea 20,0 min-an igarotzen da. Kalkulatu metatutako Ag-ren masa (M=107,868 g·mol⁻¹).','Ag⁺+e⁻→Ag(s). 1,50 A-ko korrontea 20,0 min-an igarotzen da. Kalkulatu metatutako Ag-ren masa (M=107,868 g·mol⁻¹).'),parts:[{q:b('m(Ag) (g)','m(Ag) (g)'),ans:2.012,tol:0.02}],hints:[b('Karga Q=It kalkulatu.','Karga Q=It kalkulatu.'),b('Ag⁺ mol bakoitzeko e⁻ mol bat behar da.','Ag⁺ mol bakoitzeko e⁻ mol bat behar da.')],sol:[b('Q=1,50·20·60=1800 C; ne=1800/96485=0,018656 mol.','Q=1,50·20·60=1800 C; ne=1800/96485=0,018656 mol.'),b('n(Ag)=ne eta m=0,018656·107,868=<b>2,012 g</b>.','n(Ag)=ne eta m=0,018656·107,868=<b>2,012 g</b>.')],res:'2,012 g Ag',check:b('Ag⁺-k karga positibo bakarra du: 1 e⁻/Ag atomo.','Ag⁺-k karga positibo bakarra du: 1 e⁻/Ag atomo.'),errs:b('Ag-ren erdi-erreakzioan 2 e⁻ sartzea.','Ag-ren erdi-erreakzioan 2 e⁻ sartzea.')},
 {id:'EL-05',lvl:1,skill:b('Faraday eta gas ideala','Faraday eta gas ideala'),title:b('Hidrogeno-burbuilen bolumena','Hidrogeno-burbuilen bolumena'),q:b('2H⁺+2e⁻→H₂(g). 2,00 A-ko korrontea 9650 s-an pasatzen da. Kalkulatu sortutako H₂ bolumena 298,15 K eta 1,00 atm-an. Erabili R=0,082057 L·atm·mol⁻¹·K⁻¹.','2H⁺+2e⁻→H₂(g). 2,00 A-ko korrontea 9650 s-an pasatzen da. Kalkulatu sortutako H₂ bolumena 298,15 K eta 1,00 atm-an. Erabili R=0,082057 L·atm·mol⁻¹·K⁻¹.'),parts:[{q:b('V(H₂) (L)','V(H₂) (L)'),ans:2.447,tol:0.02}],hints:[b('Karga eta elektroi-molak kalkulatu; e⁻:H₂ erlazioa 2:1 da.','Karga eta elektroi-molak kalkulatu; e⁻:H₂ erlazioa 2:1 da.'),b('Erabili PV=nRT gas-bolumenerako.','Erabili PV=nRT gas-bolumenerako.')],sol:[b('Q=It=2,00·9650=19300 C; ne=19300/96485=0,20003 mol; n(H₂)=0,10002 mol.','Q=It=2,00·9650=19300 C; ne=19300/96485=0,20003 mol; n(H₂)=0,10002 mol.'),b('V=nRT/P=0,10002·0,082057·298,15/1=<b>2,447 L</b>.','V=nRT/P=0,10002·0,082057·298,15/1=<b>2,447 L</b>.')],res:'2,447 L H₂',check:b('Bi elektroi mol H₂ mol bakoitzeko; emaitza 0,1 mol inguruko gas-bolumenarekin bat dator.','Bi elektroi mol H₂ mol bakoitzeko; emaitza 0,1 mol inguruko gas-bolumenarekin bat dator.'),errs:b('e⁻-molak H₂ mol gisa hartzea edo T Celsiusetan sartzea.','e⁻-molak H₂ mol gisa hartzea edo T Celsiusetan sartzea.')},
 {id:'EL-06',lvl:2,skill:b('Lehia eta gaintentsioa','Lehia eta gaintentsioa'),title:b('NaCl urtsua: uraren eta sodioaren lehia','NaCl urtsua: uraren eta sodioaren lehia'),q:b('pH 7-an, Eteor(H₂O/H₂)=−0,414 V eta E°(Na⁺/Na)=−2,714 V; η(H₂)=0,350 V. Anodoan Eteor(O₂/H₂O)=+0,815 V, E°(Cl₂/Cl⁻)=+1,358 V; η(O₂)=0,450 V. Katodoan eta anodoan zein espezie hautatzen da? Kalkulatu iturri idealaren gutxieneko tentsioa, kloroaren gaintentsiorik ez dagoela emanda.','pH 7-an, Eteor(H₂O/H₂)=−0,414 V eta E°(Na⁺/Na)=−2,714 V; η(H₂)=0,350 V. Anodoan Eteor(O₂/H₂O)=+0,815 V, E°(Cl₂/Cl⁻)=+1,358 V; η(O₂)=0,450 V. Katodoan eta anodoan zein espezie hautatzen da? Kalkulatu iturri idealaren gutxieneko tentsioa, kloroaren gaintentsiorik ez dagoela emanda.'),parts:[{q:b('Katodoan Eeraginkor handiena (V)','Katodoan Eeraginkor handiena (V)'),ans:-0.764,abs:0.01},{q:b('Emin ideal (V)','Emin ideal (V)'),ans:2.122,abs:0.02}],hints:[b('Katodoan E−η; hautatu E handiena.','Katodoan E−η; hautatu E handiena.'),b('Anodoan E+η; hautatu E txikiena. Eaplik,min=Ean−Ekat.','Anodoan E+η; hautatu E txikiena. Eaplik,min=Ean−Ekat.')],sol:[b('Katodoko urarentzat E=−0,414−0,350=−0,764 V; Na⁺/Na=−2,714 V → ura erreduzitzen da eta H₂ sortzen da.','Katodoko urarentzat E=−0,414−0,350=−0,764 V; Na⁺/Na=−2,714 V → ura erreduzitzen da eta H₂ sortzen da.'),b('Anodoko O₂ parearen E=0,815+0,450=1,265 V; Cl₂/Cl⁻ parearen E=1,358 V → kloruroa oxidatzen da. Ezelda=−0,764−1,358=−2,122 V, beraz iturri idealak <b>2,122 V</b> gutxienez ematen du.','Anodoko O₂ parearen E=0,815+0,450=1,265 V; Cl₂/Cl⁻ parearen E=1,358 V → kloruroa oxidatzen da. Ezelda=−0,764−1,358=−2,122 V, beraz iturri idealak <b>2,122 V</b> gutxienez ematen du.')],res:b('Katodoa: H₂O→H₂; anodoa: Cl⁻→Cl₂; Emin=2,122 V.','Katodoa: H₂O→H₂; anodoa: Cl⁻→Cl₂; Emin=2,122 V.'),check:b('NaCl urtsuan, Na ez da metatzen ura errazago erreduzitzen delako; anodoan Kl⁻ hautagaiak E txikiagoa du.','NaCl urtsuan, Na ez da metatzen ura errazago erreduzitzen delako; anodoan Kl⁻ hautagaiak E txikiagoa du.'),errs:b('E anodo eta katodoko zeinuak alderatzean gehitu beharrean kentzea, edo E° eta E teorikoa nahastea.','E anodo eta katodoko zeinuak alderatzean gehitu beharrean kentzea, edo E° eta E teorikoa nahastea.'),rubric:b('Hautagaiak zuzen aukeratu (30 %) · η-ren noranzkoak aplikatu (30 %) · Emin ekuazio eta magnitude egokiarekin (30 %) · azalpen kimikoa (10 %).','Hautagaiak zuzen aukeratu (30 %) · η-ren noranzkoak aplikatu (30 %) · Emin ekuazio eta magnitude egokiarekin (30 %) · azalpen kimikoa (10 %).')},
 {id:'EL-07',lvl:2,skill:b('Erredukzio sekuentziala eta Faraday','Erredukzio sekuentziala eta Faraday'),title:b('Lehenik burdina, gero nikela','Lehenik burdina, gero nikela'),q:b('Disoluzio batek 0,400 mol Fe³⁺ eta Ni²⁺ gehiegi dauzka. Katodoan lehenengo Fe³⁺+e⁻→Fe²⁺, ondoren 0,750 mol Ni²⁺+2e⁻→Ni. I=2,00 A konstantea. Kalkulatu (a) karga osoa eta (b) prozesuaren denbora; (c) metatutako Ni masa. F=96485 C/mol, M(Ni)=58,693 g/mol.','Disoluzio batek 0,400 mol Fe³⁺ eta Ni²⁺ gehiegi dauzka. Katodoan lehenengo Fe³⁺+e⁻→Fe²⁺, ondoren 0,750 mol Ni²⁺+2e⁻→Ni. I=2,00 A konstantea. Kalkulatu (a) karga osoa eta (b) prozesuaren denbora; (c) metatutako Ni masa. F=96485 C/mol, M(Ni)=58,693 g/mol.'),parts:[{q:b('Q (C)','Q (C)'),ans:183321.5,tol:0.005},{q:b('t (ordu)','t (ordu)'),ans:25.461,tol:0.01},{q:b('m(Ni) (g)','m(Ni) (g)'),ans:44.02,tol:0.01}],hints:[b('Fe³⁺-ren mol bakoitzeko e⁻ bat; Ni mol bakoitzeko bi.','Fe³⁺-ren mol bakoitzeko e⁻ bat; Ni mol bakoitzeko bi.'),b('Karga guztia n(e⁻)F da; denbora Q/I.','Karga guztia n(e⁻)F da; denbora Q/I.')],sol:[b('n(e⁻)=0,400+2·0,750=1,900 mol. Q=1,900·96485=<b>183322 C</b>.','n(e⁻)=0,400+2·0,750=1,900 mol. Q=1,900·96485=<b>183322 C</b>.'),b('t=Q/I=183321,5/2,00=91660,8 s=25,46 h.','t=Q/I=183321,5/2,00=91660,8 s=25,46 h.'),b('m(Ni)=0,750·58,693=<b>44,02 g</b>.','m(Ni)=0,750·58,693=<b>44,02 g</b>.')],res:b('Q=1,833×10⁵ C; t=25,46 h; m(Ni)=44,02 g.','Q=1,833×10⁵ C; t=25,46 h; m(Ni)=44,02 g.'),check:b('Elektroi osoen mol kopurua 1,90 da; denborak 2 A-ko korrontean 25 h inguruko jarduna ematen du.','Elektroi osoen mol kopurua 1,90 da; denborak 2 A-ko korrontean 25 h inguruko jarduna ematen du.'),errs:b('Fe³⁺-ren urratsean 3 elektroi erabiltzea edo Ni-rentzat koefizientea ahaztea.','Fe³⁺-ren urratsean 3 elektroi erabiltzea edo Ni-rentzat koefizientea ahaztea.'),rubric:b('Sekuentzia eta koefizienteak (30 %) · karga (25 %) · denbora-unitateen bihurketa (25 %) · Ni masa eta egiaztapena (20 %).','Sekuentzia eta koefizienteak (30 %) · karga (25 %) · denbora-unitateen bihurketa (25 %) · Ni masa eta egiaztapena (20 %).')},
 {id:'EL-08',lvl:2,skill:b('Aluminioaren industria-prozesua','Aluminioaren industria-prozesua'),title:b('Aluminioaren ekoizpena eta CO₂','Aluminioaren ekoizpena eta CO₂'),q:b('Hall–Héroult-en erreakzio globala 2Al₂O₃+3C→4Al+3CO₂ da. 2,000 kg Al ekoizten dira. Kalkulatu (a) CO₂ molak eta (b) CO₂ masa. M(Al)=26,982 g/mol; M(CO₂)=44,01 g/mol.','La reacción global de Hall–Héroult es 2Al₂O₃+3C→4Al+3CO₂. Se producen 2,000 kg de Al. Calcula (a) los moles de CO₂ y (b) su masa. M(Al)=26,982 g/mol; M(CO₂)=44,01 g/mol.'),parts:[{q:b('n(CO₂) (mol)','n(CO₂) (mol)'),ans:55.59,tol:0.01},{q:b('m(CO₂) (kg)','m(CO₂) (kg)'),ans:2.447,tol:0.01}],hints:[b('Al gramoak moletara bihurtu.','Convierte los gramos de Al a moles.'),b('Ekuazioan 4 mol Al-rentzat 3 mol CO₂ sortzen dira.','La ecuación produce 3 mol de CO₂ por cada 4 mol de Al.')],sol:[b('n(Al)=2000/26,982=74,12 mol; n(CO₂)=3/4·74,12=<b>55,59 mol</b>.','n(Al)=2000/26,982=74,12 mol; n(CO₂)=3/4·74,12=<b>55,59 mol</b>.'),b('m(CO₂)=55,5926·44,01=2446,6 g=<b>2,447 kg</b>.','m(CO₂)=55,5926·44,01=2446,6 g=<b>2,447 kg</b>.')],res:b('55,59 mol CO₂; 2,447 kg CO₂.','55,59 mol CO₂; 2,447 kg CO₂.'),check:b('CO₂/Al erlazioa 3/4 da; karbonozko anodoaren kontsumoa barne hartu da.','La relación CO₂/Al es 3/4; se incluye el consumo del ánodo de carbono.'),errs:b('Al₂O₃-ren koefizienteak produktuen erlazio molarrarekin nahastea.','Confundir el coeficiente de Al₂O₃ con la relación molar de los productos.'),rubric:b('Al molak (25 %) · proportzio doitua (30 %) · molak eta masa (30 %) · karbonozko anodoaren jatorria azaltzea (15 %).','Moles de Al (25 %) · estequiometría ajustada (30 %) · moles y masa (30 %) · explicar el origen del carbono del ánodo (15 %).')},
 {id:'EL-09',lvl:3,skill:b('HSO₄⁻ oreka eta azido-balantzea','HSO₄⁻ oreka eta azido-balantzea'),title:b('Hidroxidoen disoluzioa pH zehatzean','Hidroxidoen disoluzioa pH zehatzean'),q:b('8,00 L-ko azken bolumenean 1,50 mol Ni(OH)₂, 2,00 mol Fe(OH)₂ eta 0,500 mol Fe(OH)₃ disolbatuko dira. NaHSO₄ disoluzioa %30,0 m/m da, ρ=1,10 g/mL, M=120,0 g/mol. Helburua pH=3,20 da; Ka(HSO₄⁻)=1,20×10⁻². Hurbilketa idealarekin, kalkulatu disoluzio azidoaren bolumena.','8,00 L-ko azken bolumenean 1,50 mol Ni(OH)₂, 2,00 mol Fe(OH)₂ eta 0,500 mol Fe(OH)₃ disolbatuko dira. NaHSO₄ disoluzioa %30,0 m/m da, ρ=1,10 g/mL, M=120,0 g/mol. Helburua pH=3,20 da; Ka(HSO₄⁻)=1,20×10⁻². Hurbilketa idealarekin, kalkulatu disoluzio azidoaren bolumena.'),parts:[{q:b('V(NaHSO₄ disoluzioa) (L)','V(NaHSO₄ disoluzioa) (L)'),ans:3.255,tol:0.015}],hints:[b('Guztizko OH baliokideak 2n(NiOH₂)+2n(FeOH₂)+3n(FeOH₃) dira.','Guztizko OH baliokideak 2n(NiOH₂)+2n(FeOH₂)+3n(FeOH₃) dira.'),b('pH helburuan [H⁺]=10⁻³·²; α=Ka/(Ka+[H⁺]) eta n(H⁺)=nOH+nH,libre.','pH helburuan [H⁺]=10⁻³·²; α=Ka/(Ka+[H⁺]) eta n(H⁺)=nOH+nH,libre.'),b('n(HSO₄)=(nOH+nH,libre)/α; bihurtu soluzio-masara eta bolumenera.','n(HSO₄)=(nOH+nH,libre)/α; bihurtu soluzio-masara eta bolumenera.')],sol:[b('n(OH baliokide)=2·1,50+2·2,00+3·0,500=8,50 mol; libreko H⁺=8,00·10⁻³·²=0,00505 mol.','n(OH baliokide)=2·1,50+2·2,00+3·0,500=8,50 mol; libreko H⁺=8,00·10⁻³·²=0,00505 mol.'),b('α=0,012/(0,012+10⁻³·²)=0,9500; n(NaHSO₄)=(8,50+0,00505)/0,9500=8,952 mol.','α=0,012/(0,012+10⁻³·²)=0,9500; n(NaHSO₄)=(8,50+0,00505)/0,9500=8,952 mol.'),b('Disoluzio-masa=8,952·120/0,300=3581 g; V=3581/1,10=3255 mL=<b>3,255 L</b>.','Disoluzio-masa=8,952·120/0,300=3581 g; V=3581/1,10=3255 mL=<b>3,255 L</b>.')],res:'3,255 L NaHSO₄ disoluzio',check:b('Disoluzioaren 8,952 mol-etik ≈8,505 mol disoziatzen dira; 8,50 neutralizatzen dituzte eta ≈0,005 mol libre geratzen dira.','Disoluzioaren 8,952 mol-etik ≈8,505 mol disoziatzen dira; 8,50 neutralizatzen dituzte eta ≈0,005 mol libre geratzen dira.'),errs:b('HSO₄⁻ guztiz disoziatuta dagoela hartzea edo dentsitatea kg/L-rekin oker bihurtzea.','HSO₄⁻ guztiz disoziatuta dagoela hartzea edo dentsitatea kg/L-rekin oker bihurtzea.'),rubric:b('OH baliokideak (25 %) · HSO₄⁻ oreka eta pH (30 %) · purutasunaren aplikazioa (20 %) · masa-dentsitate bihurketa (25 %).','OH baliokideak (25 %) · HSO₄⁻ oreka eta pH (30 %) · purutasunaren aplikazioa (20 %) · masa-dentsitate bihurketa (25 %).')},
 {id:'EL-10',lvl:3,skill:b('Faraday, gas nahastea eta energia','Faraday, gas nahastea eta energia'),title:b('Uraren elektrolisia: gas-bolumenak eta energia','Uraren elektrolisia: gas-bolumenak eta energia'),q:b('2H₂O(l)→2H₂(g)+O₂(g). I=3,00 A 1,00 h-an; E=2,00 V konstantea. Kalkulatu (a) H₂ molak, (b) O₂ bolumena 298,15 K eta 1,00 atm-an, eta (c) energia kontsumitua.','2H₂O(l)→2H₂(g)+O₂(g). I=3,00 A 1,00 h-an; E=2,00 V konstantea. Kalkulatu (a) H₂ molak, (b) O₂ bolumena 298,15 K eta 1,00 atm-an, eta (c) energia kontsumitua.'),parts:[{q:b('n(H₂) (mol)','n(H₂) (mol)'),ans:0.05597,tol:0.01},{q:b('V(O₂) (L)','V(O₂) (L)'),ans:0.685,tol:0.015},{q:b('W (kJ)','W (kJ)'),ans:21.6,tol:0.01}],hints:[b('t=3600 s; Q=It.','t=3600 s; Q=It.'),b('Erreakzio globalak Q=4Fn(O₂)=2Fn(H₂) lotzen ditu.','Erreakzio globalak Q=4Fn(O₂)=2Fn(H₂) lotzen ditu.'),b('W=QE; gasarentzat PV=nRT.','W=QE; gasarentzat PV=nRT.')],sol:[b('Q=3,00·3600=10800 C; ne=10800/96485=0,11193 mol. n(H₂)=ne/2=<b>0,05597 mol</b>.','Q=3,00·3600=10800 C; ne=10800/96485=0,11193 mol. n(H₂)=ne/2=<b>0,05597 mol</b>.'),b('n(O₂)=ne/4=0,02798 mol; V=nRT/P=0,02798·0,082057·298,15=<b>0,685 L</b>.','n(O₂)=ne/4=0,02798 mol; V=nRT/P=0,02798·0,082057·298,15=<b>0,685 L</b>.'),b('W=QE=10800·2,00=21600 J=<b>21,6 kJ</b>. Batez besteko potentzia 6,00 W da.','W=QE=10800·2,00=21600 J=<b>21,6 kJ</b>. Batez besteko potentzia 6,00 W da.')],res:b('n(H₂)=0,05597 mol; V(O₂)=0,685 L; W=21,6 kJ.','n(H₂)=0,05597 mol; V(O₂)=0,685 L; W=21,6 kJ.'),check:b('H₂:O₂ mol-erlazioa 2:1 da; O₂ bolumena H₂-ren erdia da P eta T berean.','H₂:O₂ mol-erlazioa 2:1 da; O₂ bolumena H₂-ren erdia da P eta T berean.'),errs:b('Ekuazio globalean lau elektroi transferitzen direla ahaztea, edo 1 h=3600 s bihurtu ez izana.','Ekuazio globalean lau elektroi transferitzen direla ahaztea, edo 1 h=3600 s bihurtu ez izana.'),rubric:b('Karga eta e⁻ molak (25 %) · estekiometria (25 %) · gas ideala eta unitateak (25 %) · energia/potentzia (25 %).','Karga eta e⁻ molak (25 %) · estekiometria (25 %) · gas ideala eta unitateak (25 %) · energia/potentzia (25 %).')}
];

/* EK evita que el detector confunda el prefijo «EL» del identificador con el artículo español «el». */
X.forEach((x,i)=>{x.id='EK-'+String(i+1).padStart(2,'0');});
/* Versiones en castellano de los enunciados y soluciones de práctica. */
const exES=(i,k,s)=>{if(X[i][k]&&typeof X[i][k]==='object')X[i][k].es=s;};
const setItemES=(i,k,j,s)=>{X[i][k][j].es=s;};
exES(0,'skill','Potencial de celda y ΔG'); exES(0,'title','Energía de la electrólisis del agua'); exES(0,'q','Para 2H₂O(l)→2H₂(g)+O₂(g), ΔG°=+474,4 kJ y se transfieren 4 mol de e⁻. Calcula (a) E° (V) y (b) concluye si la reacción es espontánea.'); setItemES(0,'hints',0,'Usa ΔG°=−nFE°.'); setItemES(0,'hints',1,'Convierte 474,4 kJ a julios y toma n=4.'); setItemES(0,'sol',0,'E°=−ΔG°/(nF)=−474400/(4·96485)=<b>−1,229 V</b>.'); setItemES(0,'sol',1,'ΔG° es positivo: la reacción escrita no es espontánea y requiere trabajo externo.'); exES(0,'res','E°=−1,229 V; ΔG°>0, reacción no espontánea.'); exES(0,'check','El E negativo da ΔG positivo al aplicar ΔG=−nFE.'); exES(0,'errs','Usar kJ directamente con F o perder el signo de E.');
exES(1,'skill','Carga y masa depositada'); exES(1,'title','Recubrimiento de un objeto con cobre'); exES(1,'q','Cu²⁺+2e⁻→Cu(s). Circula una corriente de 1,80 A durante 25,0 min. Calcula (a) la carga y (b) la masa de cobre depositada en el cátodo (M=63,546 g·mol⁻¹).'); setItemES(1,'hints',0,'Convierte 25,0 min a segundos.'); setItemES(1,'hints',1,'Q=It; después ne=Q/F y nCu=ne/2.'); setItemES(1,'sol',0,'t=25,0·60=1500 s; Q=1,80·1500=<b>2700 C</b>.'); setItemES(1,'sol',1,'n(e⁻)=2700/96485=0,02798 mol; n(Cu)=0,01399 mol; m=nM=<b>0,889 g</b>.'); exES(1,'res','2700 C; 0,889 g de Cu.'); exES(1,'check','Q/F=0,02798 mol e⁻; se requieren 2 e⁻ por mol de Cu.'); exES(1,'errs','Dejar t en minutos u olvidar el coeficiente electrónico de Cu²⁺.');
exES(2,'skill','Ecuación de Nernst y pH'); exES(2,'title','Potencial del electrodo de hidrógeno'); X[2].title.eu='Hidrogeno-elektrodoaren potentziala'; exES(2,'q','A 25 °C, para 2H⁺+2e⁻→H₂(g), E°=0, [H⁺]=1,00×10⁻² M y P(H₂)=1,00 bar. Calcula E.'); setItemES(2,'hints',0,'Q=P(H₂)/[H⁺]².'); setItemES(2,'hints',1,'Sustituye en E=E°−(0,0592/2)logQ.'); setItemES(2,'sol',0,'Q=1/(10⁻²)²=10⁴.'); setItemES(2,'sol',1,'E=0−(0,0592/2)·4=<b>−0,1184 V</b>.'); exES(2,'check','Si [H⁺] fuese cuatro veces mayor, E sería más positivo; el signo es coherente.'); exES(2,'errs','Olvidar que la semirreacción implica 2 electrones o invertir Q.');
exES(3,'skill','Faraday: plata'); exES(3,'title','Deposición de una capa de plata'); exES(3,'q','Ag⁺+e⁻→Ag(s). Circula una corriente de 1,50 A durante 20,0 min. Calcula la masa de Ag depositada (M=107,868 g·mol⁻¹).'); setItemES(3,'hints',0,'Calcula la carga Q=It.'); setItemES(3,'hints',1,'Se necesita un mol de e⁻ por mol de Ag⁺.'); setItemES(3,'sol',0,'Q=1,50·20·60=1800 C; ne=1800/96485=0,018656 mol.'); setItemES(3,'sol',1,'n(Ag)=ne y m=0,018656·107,868=<b>2,012 g</b>.'); exES(3,'res','2,012 g de Ag'); exES(3,'check','Ag⁺ tiene una sola carga positiva: 1 e⁻ por átomo de Ag.'); exES(3,'errs','Usar 2 e⁻ en la semirreacción de Ag.');
exES(4,'skill','Faraday y gas ideal'); exES(4,'title','Volumen de burbujas de hidrógeno'); exES(4,'q','2H⁺+2e⁻→H₂(g). Circula una corriente de 2,00 A durante 9650 s. Calcula el volumen de H₂ producido a 298,15 K y 1,00 atm. Usa R=0,082057 L·atm·mol⁻¹·K⁻¹.'); setItemES(4,'hints',0,'Calcula la carga y los moles de e⁻; la relación e⁻:H₂ es 2:1.'); setItemES(4,'hints',1,'Aplica PV=nRT para obtener el volumen del gas.'); setItemES(4,'sol',0,'Q=It=2,00·9650=19300 C; ne=19300/96485=0,20003 mol; n(H₂)=0,10002 mol.'); setItemES(4,'sol',1,'V=nRT/P=0,10002·0,082057·298,15/1=<b>2,447 L</b>.'); exES(4,'res','2,447 L de H₂'); exES(4,'check','Se necesitan dos moles de electrones por mol de H₂; el volumen corresponde a unos 0,1 mol de gas.'); exES(4,'errs','Tomar los moles de e⁻ como moles de H₂ o introducir T en °C.');
exES(5,'skill','Competencia y sobrepotencial'); exES(5,'title','Competencia entre agua y sodio en NaCl acuoso'); exES(5,'q','A pH 7, Eteor(H₂O/H₂)=−0,414 V y E°(Na⁺/Na)=−2,714 V; η(H₂)=0,350 V. En el ánodo, Eteor(O₂/H₂O)=+0,815 V, E°(Cl₂/Cl⁻)=+1,358 V; η(O₂)=0,450 V y η(Cl₂)=0. ¿Qué especie se selecciona en cada electrodo y cuál es el voltaje mínimo ideal?'); setItemES(5,'hints',0,'En el cátodo aplica E−η y elige el E mayor.'); setItemES(5,'hints',1,'En el ánodo aplica E+η y elige el E menor. Eaplic,min=Ean−Ecat.'); setItemES(5,'sol',0,'Para la reducción catódica del agua E=−0,414−0,350=−0,764 V; Na⁺/Na=−2,714 V, así que se reduce agua y se forma H₂.'); exES(5,'errs','Restar en vez de sumar los ajustes de ánodo y cátodo, o confundir E° con el potencial de Nernst.'); exES(5,'rubric','Selección correcta de candidatos (30 %) · aplicar η con los signos adecuados (30 %) · calcular Emin con ecuación y magnitud correctas (30 %) · explicación química (10 %).');
exES(6,'skill','Reducción secuencial y Faraday'); exES(6,'title','Primero hierro, después níquel'); exES(6,'q','Una disolución contiene 0,400 mol de Fe³⁺ y exceso de Ni²⁺. En el cátodo ocurre primero Fe³⁺+e⁻→Fe²⁺ y después se depositan 0,750 mol mediante Ni²⁺+2e⁻→Ni. I=2,00 A constante. Calcula (a) la carga total, (b) el tiempo de proceso y (c) la masa de Ni depositada. F=96485 C/mol, M(Ni)=58,693 g/mol.'); setItemES(6,'hints',0,'Un mol de e⁻ por mol de Fe³⁺; dos moles de e⁻ por mol de Ni.'); setItemES(6,'hints',1,'La carga total es n(e⁻)F; el tiempo es Q/I.'); setItemES(6,'sol',0,'n(e⁻)=0,400+2·0,750=1,900 mol. Q=1,900·96485=<b>183322 C</b>.'); setItemES(6,'sol',1,'t=Q/I=183321,5/2,00=91660,8 s=25,46 h.'); setItemES(6,'sol',2,'m(Ni)=0,750·58,693=<b>44,02 g</b>.'); exES(6,'res','Q=1,833×10⁵ C; t=25,46 h; m(Ni)=44,02 g.'); exES(6,'check','Se transfieren 1,90 mol de e⁻; a 2 A, el tiempo resultante es de unas 25 h.'); exES(6,'errs','Usar tres electrones en el paso Fe³⁺ o olvidar el coeficiente de Ni²⁺.'); exES(6,'rubric','Secuencia y coeficientes (30 %) · carga (25 %) · conversión de unidades de tiempo (25 %) · masa de Ni y comprobación (20 %).');
exES(7,'skill','Proceso industrial del aluminio'); exES(7,'title','Producción de aluminio y CO₂'); exES(7,'q','La reacción global de Hall–Héroult es 2Al₂O₃+3C→4Al+3CO₂. Se producen 2,000 kg de Al. Calcula (a) los moles de CO₂ y (b) su masa. M(Al)=26,982 g/mol; M(CO₂)=44,01 g/mol.'); X[7].q.eu='Hall–Héroult-en erreakzio globala 2Al₂O₃+3C→4Al+3CO₂ da. 2,000 kg Al ekoizten dira. Kalkulatu (a) CO₂ molak eta (b) CO₂ masa. M(Al)=26,982 g/mol; M(CO₂)=44,01 g/mol.'; setItemES(7,'hints',0,'Convierte la masa de Al a moles.'); setItemES(7,'hints',1,'La ecuación forma 3 mol de CO₂ por cada 4 mol de Al.'); exES(7,'check','La relación CO₂/Al es 3/4; se incluye el consumo del ánodo de carbono.'); X[7].check.eu='CO₂/Al erlazioa 3/4 da; karbonozko anodoaren kontsumoa barne hartu da.'; exES(7,'errs','Confundir los coeficientes de Al₂O₃ con la relación molar entre los productos.'); exES(7,'rubric','Moles de Al (25 %) · estequiometría ajustada (30 %) · moles y masa (30 %) · explicar el origen del carbono del ánodo (15 %).'); X[7].rubric.eu='Al molak (25 %) · proportzio doitua (30 %) · molak eta masa (30 %) · karbonozko anodoaren jatorria azaltzea (15 %).';
exES(8,'skill','Equilibrio de HSO₄⁻ y balance ácido'); exES(8,'title','Disolución de hidróxidos a un pH concreto'); exES(8,'q','En un volumen final de 8,00 L se disuelven 1,50 mol de Ni(OH)₂, 2,00 mol de Fe(OH)₂ y 0,500 mol de Fe(OH)₃. La disolución de NaHSO₄ es del 30,0 % en masa, ρ=1,10 g/mL, M=120,0 g/mol. El pH objetivo es 3,20; Ka(HSO₄⁻)=1,20×10⁻². Con la aproximación ideal, calcula el volumen de disolución ácida.'); setItemES(8,'hints',0,'Los equivalentes totales de OH son 2n(Ni(OH)₂)+2n(Fe(OH)₂)+3n(Fe(OH)₃).'); setItemES(8,'hints',1,'Al pH objetivo, [H⁺]=10⁻³·²; α=Ka/(Ka+[H⁺]) y n(H⁺)=nOH+nH,libre.'); setItemES(8,'hints',2,'n(HSO₄⁻)=(nOH+nH,libre)/α; convierte a masa y volumen de disolución.'); setItemES(8,'sol',0,'n(equiv. OH)=2·1,50+2·2,00+3·0,500=8,50 mol; H⁺ libre=8,00·10⁻³·²=0,00505 mol.'); setItemES(8,'sol',1,'α=0,012/(0,012+10⁻³·²)=0,9500; n(NaHSO₄)=(8,50+0,00505)/0,9500=8,952 mol.'); setItemES(8,'sol',2,'Masa de disolución=8,952·120/0,300=3581 g; V=3581/1,10=3255 mL=<b>3,255 L</b>.'); exES(8,'res','3,255 L de disolución de NaHSO₄'); exES(8,'check','De 8,952 mol de sal se disocian ≈8,505 mol; 8,50 neutralizan los hidróxidos y quedan ≈0,005 mol libres.'); exES(8,'errs','Suponer disociación completa de HSO₄⁻ o convertir mal la densidad.'); exES(8,'rubric','Equivalentes OH (25 %) · equilibrio HSO₄⁻ y pH (30 %) · aplicar la pureza (20 %) · conversiones de masa y densidad (25 %).');
exES(9,'skill','Faraday, mezcla de gases y energía'); exES(9,'title','Electrólisis del agua: volúmenes de gas y energía'); exES(9,'q','2H₂O(l)→2H₂(g)+O₂(g). I=3,00 A durante 1,00 h; E=2,00 V constante. Calcula (a) los moles de H₂, (b) el volumen de O₂ a 298,15 K y 1,00 atm, y (c) la energía consumida.'); setItemES(9,'hints',0,'t=3600 s; Q=It.'); setItemES(9,'hints',1,'La reacción global relaciona Q=4Fn(O₂)=2Fn(H₂).'); setItemES(9,'hints',2,'W=QE; para el gas, PV=nRT.'); setItemES(9,'sol',0,'Q=3,00·3600=10800 C; ne=10800/96485=0,11193 mol. n(H₂)=ne/2=<b>0,05597 mol</b>.'); setItemES(9,'sol',1,'n(O₂)=ne/4=0,02798 mol; V=nRT/P=0,02798·0,082057·298,15=<b>0,685 L</b>.'); setItemES(9,'sol',2,'W=QE=10800·2,00=21600 J=<b>21,6 kJ</b>. La potencia media es 6,00 W.'); exES(9,'res','n(H₂)=0,05597 mol; V(O₂)=0,685 L; W=21,6 kJ.'); exES(9,'check','La relación molar H₂:O₂ es 2:1; a la misma presión y temperatura, el volumen de O₂ es la mitad del de H₂.'); exES(9,'errs','Olvidar los cuatro electrones de la reacción global o no convertir 1 h a 3600 s.'); exES(9,'rubric','Carga y moles de e⁻ (25 %) · estequiometría (25 %) · gas ideal y unidades (25 %) · energía y potencia (25 %).');
